parameters.jsCode:
// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($env.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($env.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

const url  = site + '/invite/' + encodeURIComponent(d.slug);
const dash = site + '/dashboard/' + encodeURIComponent(d.event_id);
const askConsent = !d.has_consent && !d.is_showcased;

const bodyHtml = `
  <p style="margin:0 0 18px;">Hi ${esc(d.owner_name)}, congratulations. Here is what <strong>${esc(d.title)}</strong> did.</p>
  <div style="margin:0 0 8px;">
    ${stat('Views', d.total_views)}${stat('People', d.unique_visitors)}
    ${stat('Attending', d.rsvp_yes)}${stat('Guests', d.total_heads)}
    ${stat('Blessings', d.blessings)}${Number(d.countries) > 1 ? stat('Countries', d.countries) : ''}
  </div>
  ${Number(d.countries) > 1
    ? '<p style="margin:0 0 18px;color:#6b615e;font-size:14px;">Your invitation was opened from <strong>' + d.countries + ' countries</strong>.</p>'
    : '<div style="height:10px;"></div>'}
  ${Number(d.blessings) > 0
    ? '<p style="margin:0 0 18px;"><strong>' + d.blessings + ' people</strong> left you a message. They are still on your invitation, and they will stay there: <a href="' + url + '" style="color:' + brand + ';">read them again</a>.</p>'
    : ''}
  ${askConsent ? `<div style="background:#faf7f5;border-radius:12px;padding:18px 20px;margin:0 0 18px;">
      <div style="font-weight:600;color:#1f1a19;margin-bottom:7px;">May we show it to other couples?</div>
      <p style="margin:0 0 12px;font-size:14px;line-height:1.6;color:#453c3a;">
        If you say yes, we make a <strong>sanitised copy</strong> for our showcase \u2014 addresses reduced to the city, and every phone number, guest name and RSVP removed. You can withdraw it at any time and the copy comes down immediately. Your own invitation is untouched either way.
      </p>
      <a href="${dash}#showcase" style="color:${brand};font-weight:600;text-decoration:none;">Decide on your dashboard \u2192</a>
    </div>` : ''}
  <p style="margin:0;font-size:14px;color:#6b615e;">If Amantrika made this easier, telling one other family is the kindest thing you could do for us.</p>`;

return { json: {
  dedupe_key: d.dedupe_key,
  to: d.owner_email,
  stored: {
    event_id: d.event_id, slug: d.slug, title: d.title,
    total_views: d.total_views, unique_visitors: d.unique_visitors,
    rsvp_yes: d.rsvp_yes, blessings: d.blessings, countries: d.countries,
    asked_consent: askConsent, dedupe_key: d.dedupe_key,
    subject: 'How ' + d.title + ' went \u2014 ' + d.total_views + ' views, ' + d.rsvp_yes + ' attending',
    html: shell('How it went', bodyHtml, 'Open your dashboard', dash,
      `<a href="${unsub('digest')}" style="color:#8a7d7a;">Unsubscribe</a>`),
    text: 'How ' + d.title + ' went\n\n' + d.total_views + ' views \u00b7 ' + d.unique_visitors
      + ' people \u00b7 ' + d.rsvp_yes + ' attending \u00b7 ' + d.blessings + ' blessings\n\n' + dash,
    unsubscribe: unsub('digest'),
  },
} };

parameters.jsonBody:
={{ JSON.stringify({
  from: $env.AMANTRIKA_EMAIL_FROM,
  to: [ $json.recipient ],
  subject: $json.payload.subject,
  html: $json.payload.html,
  text: $json.payload.text,
  headers: $json.payload.unsubscribe
    ? { 'List-Unsubscribe': '<' + $json.payload.unsubscribe + '>',
        'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' }
    : {}
}) }}
